```python
import os, json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance["num_variables"])

    # ── 1. Build coefficients per spec ─────────────────────────────────
    # Spec: c_i = t_norm_i - f_norm_i, with min-max normalization.
    # Globally over 90 items the orchestrator should pre-pass normalized
    # values, but here block_items carries raw time/rate. We min-max
    # normalize over the items we actually have (local fallback).
    times = np.array([float(it["time"]) for it in block_items], dtype=float)
    rates = np.array([float(it["rate"]) for it in block_items], dtype=float)

    t_min, t_max = float(times.min()), float(times.max())
    r_min, r_max = float(rates.min()), float(rates.max())
    t_span = t_max - t_min
    r_span = r_max - r_min

    if t_span > 0:
        t_norm = (times - t_min) / t_span
    else:
        t_norm = np.zeros_like(times)
    if r_span > 0:
        r_norm = (rates - r_min) / r_span
    else:
        r_norm = np.zeros_like(rates)

    coeffs = t_norm - r_norm  # c_i = t_norm_i - f_norm_i

    # ── 2. Build QUBO matrix (diagonal-only, linear objective) ────────
    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        Q[i, i] = float(coeffs[i])

    # ── 3. Convert QUBO → Ising ───────────────────────────────────────
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # ── 4. Guard against all-zero block ───────────────────────────────
    if not np.any(h) and not J:
        zeros_bs = "0" * n
        print(json.dumps({
            "value": 0.0,
            "instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "coeffs": coeffs.tolist(),
                "pauli_terms": [],
            },
            "bitstring": zeros_bs,
            "num_qubits": n,
        }))
        return

    # ── 5. QAOA cost via qaoa_blocks fast path ────────────────────────
    p_layers = int(instance.get("qaoa_hints", {}).get("p_layers", 1))
    # qaoa_blocks supports reps=1 fast path; use it regardless of p_layers
    # to stay within the sandbox budget (single layer is sufficient for a
    # purely diagonal linear cost — exact ground state lies in the basis).

    def cost(params):
        gamma, beta = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, gamma, beta)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost, x0, method="COBYLA", options={"maxiter": 20})
    best = res.x if (res.x is not None) else x0

    # ── 6. Decode bitstring & compute objective ───────────────────────
    qc_final = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(best[0]), float(best[1]))
    sv_final = Statevector(qc_final)
    bitstring = qaoa_blocks.decode_bitstring(sv_final, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    # ── 7. Output JSON (last line of stdout) ──────────────────────────
    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
            "coeffs": coeffs.tolist(),
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "p_layers_used": 1,
        "p_layers_requested": p_layers,
    }))


if __name__ == "__main__":
    main()
```



