import os, json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance.get("num_variables", 0))

    # ── 1. Build n x n QUBO from spec formula ─────────────────────────────
    # h_i = -(1/3) * rate_i_norm + (1/3) * time_i_norm + (1/3)
    rates = np.array([float(it.get("rate", 0.0)) for it in block_items], dtype=float)
    times = np.array([float(it.get("time", 0.0)) for it in block_items], dtype=float)

    max_rate = float(np.max(rates)) if rates.size > 0 and float(np.max(rates)) > 0.0 else 1.0
    max_time = float(np.max(times)) if times.size > 0 and float(np.max(times)) > 0.0 else 1.0

    rate_norm = rates / max_rate
    time_norm = times / max_time

    diag = -(1.0 / 3.0) * rate_norm + (1.0 / 3.0) * time_norm + (1.0 / 3.0)

    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        Q[i, i] = float(diag[i])

    # ── 2. QUBO → Ising ──────────────────────────────────────────────────
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # ── 3. Guard against all-zero block ──────────────────────────────────
    if not np.any(h) and not J:
        print(json.dumps({
            "value": 0.0,
            "instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "block_items": block_items,
                "pauli_terms": [],
            },
            "bitstring": "0" * n,
            "selected_ids": [],
            "num_qubits": n,
            "note": "all-zero block",
        }))
        return

    # ── 4. QAOA via qaoa_blocks (fast diagonal path) ─────────────────────
    def cost(params):
        gamma, beta = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(gamma), float(beta))
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if res.x is not None else x0

    # ── 5. Decode bitstring ──────────────────────────────────────────────
    qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(best_params[0]), float(best_params[1]))
    sv = Statevector(qc)
    bitstring = qaoa_blocks.decode_bitstring(sv, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    selected_ids = []
    for i in range(n):
        if int(bitstring[i]) == 1:
            selected_ids.append(str(block_items[i].get("id", "t" + str(i))))

    # ── 6. Output ────────────────────────────────────────────────────────
    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
            "block_items": block_items,
            "diag_coefficients": [float(v) for v in diag],
            "normalization": {
                "max_rate": max_rate,
                "max_time": max_time,
            },
        },
        "bitstring": bitstring,
        "selected_ids": selected_ids,
        "num_qubits": n,
    }))


if __name__ == "__main__":
    main()
