```python
import os, json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance["num_variables"])

    # ── 1. Build n×n QUBO matrix Q from block_items ───────────────────
    # c_i = 0.5 * (time_i / max_time) - 0.5 * (rate_i / max_rate)
    times = np.array([float(it["time"]) for it in block_items], dtype=float)
    rates = np.array([float(it["rate"]) for it in block_items], dtype=float)
    max_time = float(times.max()) if times.size and times.max() > 0 else 1.0
    max_rate = float(rates.max()) if rates.size and rates.max() > 0 else 1.0

    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        time_norm = times[i] / max_time
        rate_norm = rates[i] / max_rate
        Q[i, i] = 0.5 * time_norm - 0.5 * rate_norm

    # ── 2. Convert QUBO → Ising (h, J, const) ─────────────────────────
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # ── 3. Guard against all-zero block ───────────────────────────────
    if not np.any(h) and not J:
        print(json.dumps({
            "value": 0.0,
            "instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "pauli_terms": [],
            },
            "bitstring": "0" * n,
            "num_qubits": n,
        }))
        return

    # ── 4. QAOA via qaoa_blocks (fast diagonal path) ──────────────────
    def cost(params):
        gamma, beta = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, gamma, beta)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if res.x is not None else x0

    # ── 5. Decode bitstring via argmax ────────────────────────────────
    qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, best_params[0], best_params[1])
    sv = Statevector(qc)
    bitstring = qaoa_blocks.decode_bitstring(sv, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    selected_ids = [block_items[i]["id"] for i in range(n) if int(bitstring[i]) == 1]
    selected_times = [float(times[i]) for i in range(n) if int(bitstring[i]) == 1]
    selected_rates = [float(rates[i]) for i in range(n) if int(bitstring[i]) == 1]
    avg_time = float(np.mean(selected_times)) if selected_times else 0.0
    avg_rate = float(np.mean(selected_rates)) if selected_rates else 0.0

    # ── 6. Output ─────────────────────────────────────────────────────
    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "selected_ids": selected_ids,
        "avg_time": avg_time,
        "avg_rate": avg_rate,
        "energy_value": float(cost(best_params)),
    }))


if __name__ == "__main__":
    main()
```



