```python
import os
import json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance["num_variables"])

    # Build n x n QUBO matrix.
    # Spec objective: min_x sum_i (-g_i) * x_i,
    # g_i = (statement_cov_i_norm + faults_cov_i_norm - execution_cost_i_norm) / 3
    Q = np.zeros((n, n), dtype=float)

    if block_items:
        stmt = np.array([float(it.get("statement_cov", 0.0)) for it in block_items])
        ecost = np.array([float(it.get("execution_cost", 0.0)) for it in block_items])
        flt = np.array([float(it.get("faults_cov", 0.0)) for it in block_items])

        # Spec asks for min-max normalization over all 360 cases; only block_items are
        # supplied (block-diagonal partition), so we approximate with within-block min-max.
        def minmax(arr):
            lo = float(arr.min())
            hi = float(arr.max())
            if hi - lo < 1e-12:
                return np.zeros_like(arr, dtype=float)
            return (arr - lo) / (hi - lo)

        stmt_n = minmax(stmt)
        ecost_n = minmax(ecost)
        flt_n = minmax(flt)

        g = (stmt_n + flt_n - ecost_n) / 3.0
        for i in range(n):
            Q[i, i] = float(-g[i])

    # Convert QUBO -> Ising
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # Guard against fully degenerate block
    if not np.any(h) and not J:
        print(json.dumps({
            "value": 0.0,
            "instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "pauli_terms": [],
            },
            "bitstring": "0" * n,
            "num_qubits": n,
            "note": "all-zero block",
        }))
        return

    # QAOA cost via fast qaoa_blocks path (avoid SparsePauliOp.expectation_value)
    def cost_fn(params):
        gamma, beta = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, gamma, beta)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost_fn, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if (res.x is not None) else x0

    # Decode bitstring via argmax of |amplitude|^2
    qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(best_params[0]), float(best_params[1]))
    sv = Statevector(qc)
    bitstring = qaoa_blocks.decode_bitstring(sv, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    selected = [block_items[i].get("id", f"t{i}") for i in range(n) if int(bitstring[i]) == 1]

    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "selected_test_cases": selected,
    }))


if __name__ == "__main__":
    main()
```



