import os, json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []

    # 用 block_items 实际长度作为 n
    n = len(block_items) if block_items else int(instance["num_variables"])

    # ── 1. 抽取 cost / pcount / dist 三列 ───────────────────────────────
    costs = np.array([float(it["cost"]) for it in block_items], dtype=float)
    pcounts = np.array([float(it["pcount"]) for it in block_items], dtype=float)
    dists = np.array([float(it["dist"]) for it in block_items], dtype=float)

    # min-max 归一化到 [0,1](spec 说全 1925 案归一化,块内无法获得全局极值,
    # 按可用信息做块内归一化)。
    def minmax(v):
        lo = float(v.min())
        hi = float(v.max())
        if hi - lo < 1e-12:
            return np.zeros_like(v)
        return (v - lo) / (hi - lo)

    c_n = minmax(costs)
    p_n = minmax(pcounts)
    d_n = minmax(dists)

    # ── 2. 超参 (spec 未给具体数值,取均衡默认) ─────────────────────────
    alpha = 1.0
    beta = 1.0
    gamma = 1.0
    lam = 0.5

    # ── 3. 构 n×n 对角 QUBO Q[i,i] = α*c_i + λ - β*p_i - γ*d_i ─────────
    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        Q[i, i] = alpha * c_n[i] + lam - beta * p_n[i] - gamma * d_n[i]

    # ── 4. QUBO → Ising ────────────────────────────────────────────────
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # ── 5. 全零保护 ────────────────────────────────────────────────────
    if not np.any(h) and not J:
        x = np.zeros(n, dtype=float)
        value = float(x @ Q @ x)
        print(json.dumps({
            "value": value,
            "instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "pauli_terms": [],
            },
            "bitstring": "0" * n,
            "num_qubits": n,
            "note": "all-zero block",
        }))
        return

    # ── 6. QAOA cost via qaoa_blocks (fast path) ────────────────────────
    def cost_fn(params):
        gamma_p, beta_p = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, gamma_p, beta_p)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost_fn, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if (res.x is not None) else x0

    # ── 7. 解码最优 bitstring ──────────────────────────────────────────
    qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(best_params[0]), float(best_params[1]))
    sv = Statevector(qc)
    bitstring = qaoa_blocks.decode_bitstring(sv, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    # ── 8. 输出 JSON ───────────────────────────────────────────────────
    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "hyperparams": {
            "alpha": alpha,
            "beta": beta,
            "gamma": gamma,
            "lambda": lam,
        },
    }))


