            label[i] = "Z"
            label[j] = "Z"
            pauli_terms.append(("".join(label), float(v)))

    # Collect selected ids for downstream classical interpretation
    selected_ids = [block_items[i].get("id") for i in range(n) if int(x[i]) == 1]

    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
            "pauli_terms": pauli_terms,
            "ising_const": float(ising_const),
