import os, json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance["num_variables"])

    # ── 1. Build n×n QUBO Q from block_items per spec ─────────────────
    # spec: c_i = exec_cost_i_norm - statement_cov_i_norm - faults_cov_i_norm
    # 每项按各自最大值归一化(0/1 加权)
    Q = np.zeros((n, n), dtype=float)
    if n > 0:
        exec_arr = np.array([float(it.get("execution_cost", 0.0)) for it in block_items], dtype=float)
        stmt_arr = np.array([float(it.get("statement_cov", 0.0)) for it in block_items], dtype=float)
        fault_arr = np.array([float(it.get("faults_cov", 0.0)) for it in block_items], dtype=float)

        exec_max = float(exec_arr.max()) if exec_arr.size > 0 else 0.0
        stmt_max = float(stmt_arr.max()) if stmt_arr.size > 0 else 0.0
        fault_max = float(fault_arr.max()) if fault_arr.size > 0 else 0.0

        exec_norm = exec_arr / exec_max if exec_max > 0 else np.zeros_like(exec_arr)
        stmt_norm = stmt_arr / stmt_max if stmt_max > 0 else np.zeros_like(stmt_arr)
        fault_norm = fault_arr / fault_max if fault_max > 0 else np.zeros_like(fault_arr)

        c = exec_norm - stmt_norm - fault_norm
        for i in range(n):
            Q[i, i] = float(c[i])

    # ── 2. Convert QUBO → Ising ───────────────────────────────────────
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # ── 3. Guard against all-zero block ───────────────────────────────
    if not np.any(h) and not J:
        print(json.dumps({"value": 0.0, "instance": {
            "type": "qubo", "matrix": Q.tolist(), "num_variables": n,
            "pauli_terms": []}, "bitstring": "0" * n, "num_qubits": n,
            "note": "all-zero block"}))
        return

    # ── 4. QAOA cost — qaoa_blocks fast path ──────────────────────────
    def cost(params):
        gamma, beta = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, gamma, beta)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if res.x is not None else x0

    # ── 5. Decode bitstring ───────────────────────────────────────────
    qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(best_params[0]), float(best_params[1]))
    sv = Statevector(qc)
    bitstring = qaoa_blocks.decode_bitstring(sv, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    # ── 6. Output ─────────────────────────────────────────────────────
    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
        },
        "bitstring": bitstring,
        "num_qubits": n,
    }))


if __name__ == "__main__":
    main()
```



