```python
import os
import json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance["num_variables"])

    # 1. Build diagonal QUBO from spec formula:
    #    c_i = execution_cost_i + 1 - statement_cov_i - faults_cov_i
    Q = np.zeros((n, n), dtype=float)
    for i, item in enumerate(block_items):
        cost_i = float(item.get("execution_cost", 0.0))
        scov_i = float(item.get("statement_cov", 0.0))
        fcov_i = float(item.get("faults_cov", 0.0))
        Q[i, i] = cost_i + 1.0 - scov_i - fcov_i

    # 2. QUBO -> Ising
    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    # 3. Guard against all-zero block
    if not np.any(h) and not J:
        bitstring = "0" * n
        x = np.zeros(n, dtype=float)
        value = float(x @ Q @ x)
        print(json.dumps({
            "value": value,
            "instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "pauli_terms": [],
            },
            "bitstring": bitstring,
            "num_qubits": n,
            "note": "all-zero block",
        }))
        return

    # 4. QAOA cost evaluation via qaoa_blocks (fast diagonal path)
    def cost(params):
        gamma, beta = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, gamma, beta)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if res.x is not None else x0

    # 5. Decode bitstring via argmax of final statevector
    qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(best_params[0]), float(best_params[1]))
    sv = Statevector(qc)
    bitstring = qaoa_blocks.decode_bitstring(sv, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    # 6. Output
    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
        },
        "bitstring": bitstring,
        "num_qubits": n,
    }))


if __name__ == "__main__":
    main()
```



