    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "selected_indices": [i for i, b in enumerate(bitstring) if b == "1"],
        "selected_ids": [block_items[i].get("id") for i, b in enumerate(bitstring) if b == "1"],
