```python
import os
import json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance["num_variables"])

    weights = instance.get("weights", {}) or {}
    alpha = float(weights.get("alpha", 1.0 / 3.0))
    beta = float(weights.get("beta", 1.0 / 3.0))
    gamma = float(weights.get("gamma", 1.0 / 3.0))
    delta = float(weights.get("delta", 0.05))

    costs_raw = np.array([float(it.get("execution_cost", 0.0)) for it in block_items], dtype=float)
    stmts_raw = np.array([float(it.get("statement_cov", 0.0)) for it in block_items], dtype=float)
    faults_raw = np.array([float(it.get("faults_cov", 0.0)) for it in block_items], dtype=float)

    max_cost = float(costs_raw.max()) if costs_raw.size and costs_raw.max() > 0.0 else 1.0
    max_stmt = float(stmts_raw.max()) if stmts_raw.size and stmts_raw.max() > 0.0 else 1.0
    max_fault = float(faults_raw.max()) if faults_raw.size and faults_raw.max() > 0.0 else 1.0

    cost_norm = costs_raw / max_cost
    stmt_norm = stmts_raw / max_stmt
    fault_norm = faults_raw / max_fault

    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        Q[i, i] = alpha * cost_norm[i] - beta * stmt_norm[i] - gamma * fault_norm[i] + delta

    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    if not np.any(h) and not J:
        bitstring = "0" * n
        x = np.zeros(n, dtype=float)
        value = float(x @ Q @ x)
        print(json.dumps({
            "value": value,
            "instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "pauli_terms": [],
            },
            "bitstring": bitstring,
            "num_qubits": n,
            "note": "all-zero block",
        }))
        return

    def cost_fn(params):
        g, b = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, g, b)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost_fn, x0, method="COBYLA", options={"maxiter": 20})
    best = res.x if (res.x is not None) else x0

    qc_final = qaoa_blocks.qaoa_diag_circuit(n, h, J, float(best[0]), float(best[1]))
    sv_final = Statevector(qc_final)
    bitstring = qaoa_blocks.decode_bitstring(sv_final, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "selected_indices": [i for i, b in enumerate(bitstring) if b == "1"],
    }))


if __name__ == "__main__":
    main()
```



